/**
 * RSC handler registry for managing per-project handlers
 *
 * Supports optional cache injection for testing.
 *
 * @module rsc-endpoints/handler-registry
 */
import { RSCDevServerHandler } from "../orchestrators/index.js";
import { getConfiguredRSCDependencyVersionIdentity, } from "../orchestrators/handler.js";
import { LRUCache } from "../../../../utils/lru-wrapper.js";
import { registerCache } from "../../../../utils/memory/index.js";
const RSC_HANDLERS_MAX_ENTRIES = 50;
const RSC_HANDLERS_TTL_MS = 60 * 60 * 1000; // 1 hour
const RSC_HANDLERS_CLEANUP_INTERVAL_MS = 300_000; // 5 minutes
let rscHandlersByProject = null;
let cacheRegistered = false;
/** Injected cache for testing (overrides default LRUCache) */
let injectedCache = null;
const handlerKeysByProject = new Map();
const handlerProjectByCacheKey = new Map();
function untrackHandlerCacheKey(cacheKey) {
    const projectKey = handlerProjectByCacheKey.get(cacheKey);
    if (!projectKey)
        return;
    handlerProjectByCacheKey.delete(cacheKey);
    const projectKeys = handlerKeysByProject.get(projectKey);
    projectKeys?.delete(cacheKey);
    if (projectKeys?.size === 0)
        handlerKeysByProject.delete(projectKey);
}
function getHandlersCache() {
    if (injectedCache)
        return injectedCache;
    if (rscHandlersByProject)
        return rscHandlersByProject;
    rscHandlersByProject = new LRUCache({
        maxEntries: RSC_HANDLERS_MAX_ENTRIES,
        ttlMs: RSC_HANDLERS_TTL_MS,
        cleanupIntervalMs: RSC_HANDLERS_CLEANUP_INTERVAL_MS,
        onEvict: (cacheKey) => untrackHandlerCacheKey(cacheKey),
    });
    if (!cacheRegistered) {
        registerCache("rsc-handlers", () => ({
            name: "rsc-handlers",
            entries: rscHandlersByProject?.size ?? 0,
            maxEntries: RSC_HANDLERS_MAX_ENTRIES,
        }));
        cacheRegistered = true;
    }
    return rscHandlersByProject;
}
export function getRSCHandler(projectDir, projectId, options = {}) {
    const baseKey = projectId ?? projectDir;
    const appDir = options.config?.directories?.app ?? "app";
    const mode = options.mode ?? "production";
    const dependencyVersionIdentity = getConfiguredRSCDependencyVersionIdentity(options.config);
    const pinningEnabled = options.dependencyPinningEnabled === true;
    const cacheKey = JSON.stringify([
        baseKey,
        options.isLocalProject === true,
        mode,
        appDir,
        ...dependencyVersionIdentity,
        ...(options.contentSourceId || options.releaseId
            ? [options.releaseId ?? null, options.contentSourceId ?? null]
            : []),
        ...(pinningEnabled && options.branch ? [options.branch] : []),
    ]);
    const cache = getHandlersCache();
    const existing = cache.get(cacheKey);
    if (existing)
        return existing;
    const handler = new RSCDevServerHandler(projectDir, options);
    cache.set(cacheKey, handler);
    const projectKeys = handlerKeysByProject.get(baseKey) ?? new Set();
    projectKeys.add(cacheKey);
    handlerKeysByProject.set(baseKey, projectKeys);
    handlerProjectByCacheKey.set(cacheKey, baseKey);
    return handler;
}
export function invalidateRSCHandlersForProject(projectDir, projectId) {
    const projectKey = projectId ?? projectDir;
    const cacheKeys = handlerKeysByProject.get(projectKey);
    if (!cacheKeys)
        return;
    const cache = getHandlersCache();
    for (const cacheKey of [...cacheKeys]) {
        cache.delete(cacheKey);
        untrackHandlerCacheKey(cacheKey);
    }
    handlerKeysByProject.delete(projectKey);
}
export function __injectCacheForTests(cache) {
    injectedCache = cache;
}
export function __resetRSCHandlerForTests() {
    const cache = injectedCache ?? rscHandlersByProject;
    cache?.clear();
    handlerKeysByProject.clear();
    handlerProjectByCacheKey.clear();
}
export function __destroyRSCHandlerForTests() {
    injectedCache = null;
    rscHandlersByProject?.destroy();
    rscHandlersByProject = null;
    handlerKeysByProject.clear();
    handlerProjectByCacheKey.clear();
}
export function __getTrackedRSCHandlerKeyCountForTests() {
    return handlerProjectByCacheKey.size;
}
